**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    sort(tab.begin(), tab.end());
    int n = tab.size();

    int maxCnt = 0, minCnt = n + 1;
    int maxVal = 0, minVal = 0;
    int cnt = 1;
    for (int i = 1; i < n; i++) {
        if (tab[i] == tab[i - 1]) {
            cnt++;
        } else {
            if (cnt > maxCnt) { maxCnt = cnt; maxVal = tab[i - 1]; }
            if (cnt < minCnt) { minCnt = cnt; minVal = tab[i - 1]; }
            cnt = 1;
        }
    }
    if (cnt > maxCnt) { maxCnt = cnt; maxVal = tab[n - 1]; }
    if (cnt < minCnt) { minCnt = cnt; minVal = tab[n - 1]; }

    cout << "a) Najczesciej: " << maxVal << " (" << maxCnt << " razy)" << endl;
    cout << "b) Najrzadziej: " << minVal << " (" << minCnt << " raz)" << endl;
    return 0;
}
```

**Wyjasnienie**: Sortujemy tablice, potem w jednym przebiegu liczymy serie identycznych elementow. Dla kazdej serii porownujemy dlugosc z dotychczasowym max/min.

Weryfikacja:
- Posortowane: 3,3,3,3,5,7,7,7,9,9,12,12
- Serie: 3(4x), 5(1x), 7(3x), 9(2x), 12(2x)
- Max czestotliwosc: 3 (4 razy)
- Min czestotliwosc: 5 (1 raz)
